# race_data.py — TOUTES les données du modèle, à éditer SANS toucher au script.
#
# Contenu :
#   1. RACES_DATA   : les résultats de courses (une entrée = un appel à race())
#   2. NAME_ALIASES : corrections de graphies de noms
#
# Le script principal fait simplement :
#     from race_data import RACES_DATA, NAME_ALIASES
#
# (les startlists et les cibles de prédiction sont désormais saisies
#  directement dans le terminal quand tu lances le script)
#
# ------------------------------------------------------------------------
# COMMENT AJOUTER UNE COURSE
# ------------------------------------------------------------------------
# Colle un nouveau bloc race(...) en bas de la section 1 :
#
#     race("UTMB 2026", "2026-08", 176, """
#     1<TAB> WALMSLEY Jim<TAB>19:37:43<TAB>35-39<TAB>M<TAB> USA
#     2<TAB> MILLER Zach<TAB>19:58:58<TAB>35-39<TAB>M<TAB> USA
#     """, dnf=["Ben Dhiman", "Josh Wade"])
#
#   - Arguments : nom, date "AAAA-MM", distance en km, puis le texte collé.
#   - dplus=9900   : dénivelé positif en mètres (D+). Valeur officielle de la course ;
#                  un "# ~estim." en fin d'appel signale une valeur approximative à vérifier.
#   - max_n=10     : nombre de coureurs lus (défaut 20). À écrire seulement si != 20.
#   - dnf=[...]    : abandons connus, au format "Prénom Nom" (pas "NOM Prénom").
#   - fmt="first_last_table" : pour les tableaux où prénom et nom sont dans
#                  deux colonnes séparées (ex: George Waterfall 100k).
#   - Le `name` doit rester unique : il sert de clé pour les DNF.
#   - L'ORDRE des courses est conservé tel quel (il peut influencer les
#     égalités dans le modèle) : ajoute plutôt en fin de liste.
# ------------------------------------------------------------------------

RACES_DATA = []


def race(name, date, distance_km, results, max_n=20, dnf=(), fmt=None, dplus=None):
    """Enregistre une course dans RACES_DATA (simple conteneur, aucune logique)."""
    RACES_DATA.append({
        "name": name,
        "date": date,
        "distance_km": distance_km,
        "dplus": dplus,
        "max_n": max_n,
        "dnf": list(dnf),
        "format": fmt,
        "results": results,
    })


